import{_ as o,o as l,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Ceph Crimson/SeaStore 2021-11-10","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore 2021-11-10","date":"2021-11-10T00:00:00.000Z","updated":"2021-11-11T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","Bluestore","Bluefs","Rocksdb","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","消息码","复制","快照","克隆","虚拟化","云计算","AWS","Azure","Google Cloud","混合云","多云","存储集群","节点","磁盘","SSD","HDD","JBOD","SAN","NAS","网络","拓扑","故障域","恢复","弹性","负载均衡","缓存","压缩","去重","分层","性能调优","基准测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_SeaStore_2021-11-10.md","filePath":"posts/2021/Ceph_Crimson_SeaStore_2021-11-10.md","lastUpdated":1780459816000}'),a={name:"posts/2021/Ceph_Crimson_SeaStore_2021-11-10.md"};function t(s,e,n,h,S,d){return l(),i("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节： <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节：&quot;">​</a></h4><ol><li><strong>Journal PRs 合并</strong>：本周团队成功合并了两个 Journal PRs。</li><li><strong>PRT 结构泛化</strong>：Myeongwon 正在尝试泛化 PRT 结构，以便只有段管理器内部关注段管理器部分，从而能够在 Ceph 存储和事务管理器中无缝使用随机访问设备地址。</li><li><strong>ZNS 段管理器</strong>：Joseph 正在开发 ZNS 段管理器，并已实现大部分功能。实验室中已有几个实际的 ZNS 设备，进展顺利。</li><li><strong>Crimson 配置简化</strong>：Radik 上周主要在 Crimson 项目中工作，提交了一个 PR 以移除 Rook 中 Crimson 的特定配置需求，简化了 Kubernetes 集群中的客户端配置。</li><li><strong>中断条件问题</strong>：Barth 发现了一个与中断条件相关的问题，即在可中断未来中，全局中断条件未被清除，导致后续事件无法正确启动。该问题已在测试环境中发现，将在离线讨论中解决。</li><li><strong>C-Store 测试</strong>：Soonel 尝试在上游主分支中测试 C-Store，但发现部署工具尚未支持 C-Store，建议继续关注 Blue Store 的测试。</li><li><strong>段故障问题</strong>：上周在测试中遇到了严重的段故障问题，原因是 GC 未启动导致空间未回收。已提交 PR 修复 32 位类型溢出问题，但仍在寻找根本原因。</li><li><strong>中断条件状态</strong>：在处理 PG 事件时遇到了嵌套中断条件的问题，建议通过实现某种中断条件状态来解决。</li></ol><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题： <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题：&quot;">​</a></h4><ul><li>PRT 结构的泛化和其在 Ceph 中的应用。</li><li>ZNS 段管理器的开发进展和实际设备测试。</li><li>Crimson 配置的简化及其在 Kubernetes 集群中的应用。</li><li>中断条件问题的诊断和解决方案。</li><li>C-Store 的测试现状和未来方向。</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项： <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项：&quot;">​</a></h4><ul><li>继续推进 PRT 结构的泛化工作。</li><li>继续 ZNS 段管理器的开发和测试。</li><li>简化 Crimson 配置，移除不必要的特定配置。</li><li>解决中断条件问题，确保事件处理的正确性。</li><li>关注 Blue Store 的测试，同时探索 C-Store 的部署可能性。</li></ul><h4 id="后续的行动计划" tabindex="-1">后续的行动计划： <a class="header-anchor" href="#后续的行动计划" aria-label="Permalink to &quot;后续的行动计划：&quot;">​</a></h4><ul><li>Myeongwon 继续泛化 PRT 结构，确保其在 Ceph 中的无缝应用。</li><li>Joseph 继续 ZNS 段管理器的开发，并进行实际设备测试。</li><li>Radik 继续简化 Crimson 配置，确保其在 Kubernetes 集群中的顺利应用。</li><li>Barth 与 Jihad 离线讨论中断条件问题的解决方案。</li><li>Soonel 继续关注 Blue Store 的测试，同时探索 C-Store 的部署可能性。</li><li>解决段故障问题的根本原因，并确保 GC 的正常运行。</li></ul><h3 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h3><ul><li>会议结束，祝大家本周工作顺利。</li></ul>',11)])])}const _=o(a,[["render",t]]);export{C as __pageData,_ as default};
